    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر جداء a","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">5</span></span>(1 + 3<span class=\"rad\"><span class=\"rcd\">5</span></span>) = <span class=\"rad\"><span class=\"rcd\">5</span></span> + 15</span>"},{"quoi":"نطرح الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">5</span></span> + 15 - 13 = 2 + <span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نتيجة a","math":"<span dir=\"ltr\" class=\"expr\">a = 2 + <span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نبسّط جذر b الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">245</span></span> = <span class=\"rad\"><span class=\"rcd\">49 × 5</span></span> = 7<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نبسّط جذر b الثاني","math":"<span dir=\"ltr\" class=\"expr\">3<span class=\"rad\"><span class=\"rcd\">20</span></span> = 3<span class=\"rad\"><span class=\"rcd\">4 × 5</span></span> = 6<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نجمع حدّي <span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">5</span></span></span>","math":"<span dir=\"ltr\" class=\"expr\">7<span class=\"rad\"><span class=\"rcd\">5</span></span> - 6<span class=\"rad\"><span class=\"rcd\">5</span></span> = <span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نتيجة b","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"rad\"><span class=\"rcd\">5</span></span> - 2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">a × b = (2 + <span class=\"rad\"><span class=\"rcd\">5</span></span>)(<span class=\"rad\"><span class=\"rcd\">5</span></span> - 2)</span>"},{"quoi":"نستعمل المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(2 + <span class=\"rad\"><span class=\"rcd\">5</span></span>)(<span class=\"rad\"><span class=\"rcd\">5</span></span> - 2) = (<span class=\"rad\"><span class=\"rcd\">5</span></span>)<sup>2</sup> - 2<sup>2</sup></span>"},{"quoi":"نحسب المربّعين","math":"<span dir=\"ltr\" class=\"expr\">(<span class=\"rad\"><span class=\"rcd\">5</span></span>)<sup>2</sup> - 2<sup>2</sup> = 5 - 4</span>"},{"quoi":"نستنتج","math":"<span dir=\"ltr\" class=\"expr\">5 - 4 = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a × b = 1</span>، إذن a مقلوب b"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"مقلوب a","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">a</span></span> = b</span>"},{"quoi":"مقلوب b","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">b</span></span> = a</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">C = <span class=\"rad\"><span class=\"rcd\">5</span></span> b + 2 a</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"rad\"><span class=\"rcd\">5</span></span>(<span class=\"rad\"><span class=\"rcd\">5</span></span> - 2) + 2(2 + <span class=\"rad\"><span class=\"rcd\">5</span></span>) = 5 - 2<span class=\"rad\"><span class=\"rcd\">5</span></span> + 4 + 2<span class=\"rad\"><span class=\"rcd\">5</span></span></span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">5 - 2<span class=\"rad\"><span class=\"rcd\">5</span></span> + 4 + 2<span class=\"rad\"><span class=\"rcd\">5</span></span> = 9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">C = 9</span>"}],
